#include <bits/stdc++.h>
using namespace std;
int prec(char c){if(c=='^')return 3;if(c=='*'||c=='/')return 2;if(c=='+'||c=='-')return 1;return 0;}
int main(){string s;getline(cin,s);vector<string> out;stack<char> st;for(size_t i=0;i<s.size();){if(isspace((unsigned char)s[i])){++i;continue;}if(isalnum((unsigned char)s[i])||s[i]=='_'){size_t j=i+1;while(j<s.size()&&(isalnum((unsigned char)s[j])||s[j]=='_'||s[j]=='.'))++j;out.push_back(s.substr(i,j-i));i=j;}else if(s[i]=='('){st.push(s[i++]);}else if(s[i]==')'){while(!st.empty()&&st.top()!='('){out.push_back(string(1,st.top()));st.pop();}if(st.empty()){cout<<"Invalid parentheses\n";return 0;}st.pop();++i;}else if(string("+-*/^").find(s[i])!=string::npos){char op=s[i++];while(!st.empty()&&st.top()!='('&&(prec(st.top())>prec(op)||(prec(st.top())==prec(op)&&op!='^'))){out.push_back(string(1,st.top()));st.pop();}st.push(op);}else{cout<<"Invalid character: "<<s[i]<<'\n';return 0;}}while(!st.empty()){if(st.top()=='('){cout<<"Invalid parentheses\n";return 0;}out.push_back(string(1,st.top()));st.pop();}for(size_t i=0;i<out.size();i++)cout<<(i?" ":"")<<out[i];cout<<'\n';}
